const lv_image_dsc_t *icon_for(const char *name, int size)
{
    static const struct { const char *name; int size; const lv_image_dsc_t *img; } T[] = {
        { "fitness_center", 14, &icon_fitness_center_14 },
        { "fitness_center", 28, &icon_fitness_center_28 },
        { "rowing", 14, &icon_rowing_14 },
        { "rowing", 28, &icon_rowing_28 },
        { "directions_run", 14, &icon_directions_run_14 },
        { "directions_run", 28, &icon_directions_run_28 },
        { "hot_tub", 14, &icon_hot_tub_14 },
        { "hot_tub", 20, &icon_hot_tub_20 },
        { "hot_tub", 28, &icon_hot_tub_28 },
        { "hot_tub", 120, &icon_hot_tub_120 },
        { "bedtime", 14, &icon_bedtime_14 },
        { "bedtime", 20, &icon_bedtime_20 },
        { "bedtime", 28, &icon_bedtime_28 },
        { "bedtime", 120, &icon_bedtime_120 },
        { "directions_walk", 20, &icon_directions_walk_20 },
        { "nutrition", 20, &icon_nutrition_20 },
        { "local_fire_department", 20, &icon_local_fire_department_20 },
        { "favorite", 16, &icon_favorite_16 },
        { "trophy", 16, &icon_trophy_16 },
        { "check", 14, &icon_check_14 },
        { "check", 18, &icon_check_18 },
        { "close", 14, &icon_close_14 },
        { "bolt", 20, &icon_bolt_20 },
        { "ecg_heart", 16, &icon_ecg_heart_16 },
        { "spo2", 16, &icon_spo2_16 },
    };
    const lv_image_dsc_t *fallback = NULL;
    for(unsigned i = 0; i < sizeof T / sizeof T[0]; i++) {
        if(name && strcmp(T[i].name, name) == 0 && T[i].size == size) return T[i].img;
        if(!fallback && strcmp(T[i].name, "fitness_center") == 0 && T[i].size == size) fallback = T[i].img;
    }
    return fallback ? fallback : &icon_check_14;
}
